import React, { useState } from 'react';
import TimeBlock from './TimeBlock';

function DayPlanner({ date, entries, setEntries }) {
  const dateKey = date.toDateString();
  const dayEntry = entries[dateKey] || { morning: [], day: [], evening: [] };

  // Временные слоты с часовыми интервалами
  const timeSlots = {
    morning: [
      '06:00 - 07:00', '07:00 - 08:00', '08:00 - 09:00', '09:00 - 10:00',
      '10:00 - 11:00', '11:00 - 12:00'
    ],
    day: [
      '12:00 - 13:00', '13:00 - 14:00', '14:00 - 15:00', '15:00 - 16:00',
      '16:00 - 17:00', '17:00 - 18:00'
    ],
    evening: [
      '18:00 - 19:00', '19:00 - 20:00', '20:00 - 21:00', '21:00 - 22:00',
      '22:00 - 23:00', '23:00 - 00:00'
    ]
  };

  const timeBlocks = [
    {
      id: 'morning',
      title: '🌅 Утро',
      timeRange: '06:00 - 12:00',
      icon: '☀️',
      period: 'утро',
      slots: timeSlots.morning
    },
    {
      id: 'day',
      title: '☀️ День',
      timeRange: '12:00 - 18:00',
      icon: '🌤️',
      period: 'день',
      slots: timeSlots.day
    },
    {
      id: 'evening',
      title: '🌙 Вечер',
      timeRange: '18:00 - 00:00',
      icon: '🌙',
      period: 'вечер',
      slots: timeSlots.evening
    }
  ];

  const handleBlockUpdate = (blockId, items) => {
    setEntries({
      ...entries,
      [dateKey]: {
        ...dayEntry,
        [blockId]: items
      }
    });
  };

  const handlePrevDay = () => {
    const prevDay = new Date(date);
    prevDay.setDate(date.getDate() - 1);
    setEntries(entries);
    window.location.reload();
  };

  const handleNextDay = () => {
    const nextDay = new Date(date);
    nextDay.setDate(date.getDate() + 1);
    window.location.reload();
  };

  const handleToday = () => {
    const today = new Date();
    window.location.reload();
  };

  return (
    <div className="day-planner">
      <div className="day-navigation">
        <button onClick={handlePrevDay} className="nav-btn">←</button>
        <div className="day-title">
          <h2>
            {date.toLocaleDateString('ru-RU', {
              weekday: 'long',
              year: 'numeric',
              month: 'long',
              day: 'numeric'
            })}
          </h2>
          <button onClick={handleToday} className="today-btn">
            Сегодня
          </button>
        </div>
        <button onClick={handleNextDay} className="nav-btn">→</button>
      </div>

      <div className="time-blocks">
        {timeBlocks.map(block => (
          <TimeBlock
            key={block.id}
            id={block.id}
            title={block.title}
            timeRange={block.timeRange}
            icon={block.icon}
            period={block.period}
            timeSlots={block.slots}
            items={dayEntry[block.id]}
            onUpdate={(items) => handleBlockUpdate(block.id, items)}
          />
        ))}
      </div>
    </div>
  );
}

export default DayPlanner;
